-- Generated by render_atendimentos.py from int_acolherio_atendimentos.
-- noqa: disable=AL09,AL10,CP01,CP02,CV01,CV03,CV10,LT01,LT02,LT04,LT08,LT15
create or replace table `rj-smas-dev.dashboard_acolherio.dev_atendimentos` as
select
    a.modulo as modulo,
    a.cas as CAS,
    a.tipo_unidade as TIPO_UNIDADE,
    a.unidade_atendimento as UNIDADE_ATENDIMENTO,
    a.email_unidade as EMAIL_UNIDADE,
    a.email_cas as EMAIL_CAS,
    a.seq_atendimento as SEQ_ATENDIMENTO,
    a.data_de_atendimento as DATA_DE_ATENDIMENTO,
    a.hora_de_atendimento_original as HORA_DE_ATENDIMENTO_ORIGINAL,
    a.hora_de_atendimento as HORA_DE_ATENDIMENTO,
    a.id_usuario as ID_USUARIO,
    a.id_familia as ID_FAMILIA,
    a.nome_usuario as NOME_USUARIO,
    a.documentacao as DOCUMENTACAO,
    a.numero_documento as NUMERO_DOCUMENTO,
    a.endereco as ENDERECO,
    a.endereco_numero as ENDERECO_NUMERO,
    a.endereco_complemento as ENDERECO_COMPLEMENTO,
    a.bairro as BAIRRO,
    a.referencia_ou_comunidade as REFERENCIA_OU_COMUNIDADE,
    a.nome_atendimento_original as NOME_ATENDIMENTO_ORIGINAL,
    a.data_nascimento as DATA_NASCIMENTO,
    a.idade as IDADE,
    a.raca_cor as RACA_COR,
    a.sexo as SEXO,
    a.profissional_id as PROFISSIONAL_ID,
    a.profissional as PROFISSIONAL,
    a.profissional_cbo_original as PROFISSIONAL_CBO_ORIGINAL,
    a.profissional_cbo as PROFISSIONAL_CBO,
    a.cadastrante as CADASTRANTE,
    a.data_cadastro_atendimento as DATA_CADASTRO_ATENDIMENTO,
    a.tipo_atendimento as TIPO_ATENDIMENTO,
    a.nome_atendimento as NOME_ATENDIMENTO,
    a.idade_faixa as IDADE_FAIXA,
    a.id_atendimento as ID_ATENDIMENTO,
    a.email as EMAIL,
    a.cbo_unico_rank as cbo_unico_rank,
    a.atendimento_unico_rank as atendimento_unico_rank,
    a.projetos_sociais as PROJETOS_SOCIAIS
from (
-- Materializa a seleção uma vez para que os consumidores compartilhem os mesmos desempates.
-- Seleção de linhas de atendimento e profissional a partir dos raws do AcolheRio.
-- Mantém as partições da busca programada com desempate determinístico.
WITH base_atendimentos AS (
    SELECT
        b.id_atendimento,
        b.modulo,
        b.data_atendimento,
        cast(b.hora_atendimento AS int64) AS hora_atendimento,
        b.id_tipo_atendimento,
        b.id_profissional,
        b.id_paciente,
        b.id_unidade,
        b.data_cadastro_atendimento,
        b.flag_cancelado,
        b.id_profissional_compartilhado,
        b.id_login_cadastro,
        f.id_familia
    FROM (
-- Camada Raw: Atendimentos do Módulo Usuário
with source as (
    select
        sequs as id_unidade,
        seqatend as id_atendimento,
        seqpac as id_paciente,
        seqprof as id_profissional,
        seqlogincad as id_login_cadastro,
        seqtpatend as id_tipo_atendimento,
        seqativgrp as id_atividade_grupo,
        codclin as codigo_clinica,
        'u' as modulo,
        indatendcanc as flag_cancelado,
        dsclstprof as id_profissional_compartilhado,
        indlocalatend as local_atendimento,
        dtentrada as data_atendimento,
        datcadast as data_cadastro_atendimento,
        horaent as hora_atendimento,
        dtsaida as data_saida,
        horasai as hora_saida,
    from `rj-smas`.`brutos_acolherio_staging`.`gh_atendimentos`
)
select
    *,
    concat(id_atendimento, modulo) as id_atendimento_modulo
from source
) AS b
    LEFT JOIN (
-- Camada Raw: Vínculos de membros com famílias
with source as (
    select
        seqpac as id_paciente,
        seqfamil as id_familia,
        seqmembro as id_membro,
        seqfamilnova as id_familia_nova,
        seqmotivsaida as id_motivo_saida,
        datentrada as data_entrada,
        datsaida as data_saida,
        parentesco_responsavel_familia as parentesco_responsavel
    from  `rj-smas`.`brutos_acolherio_staging`.`gh_familias_membros`
)
select * from source
) AS f ON b.id_paciente = f.id_paciente
    WHERE f.data_saida IS null

    UNION ALL

    SELECT
        id_atendimento,
        modulo,
        data_atendimento,
        cast(hora_atendimento AS int64) AS hora_atendimento,
        id_tipo_atendimento,
        id_profissional,
        id_paciente,
        id_unidade,
        data_cadastro_atendimento,
        flag_cancelado,
        id_profissional_compartilhado,
        id_login_cadastro,
        id_familia
    FROM (
-- Camada Raw: Atendimentos do Módulo Família
with source as (
    select
        sequs as id_unidade,
        seqatend as id_atendimento,
        seqpac as id_paciente,
        seqfamil as id_familia,
        seqprof as id_profissional,
        seqlogincad as id_login_cadastro,
        seqtpatend as id_tipo_atendimento,
        'f' as modulo,
        indatendcanc as flag_cancelado,
        dsclstprof as id_profissional_compartilhado,
        indlocalatend as local_atendimento,
        dtentrada as data_atendimento,
        datcadast as data_cadastro_atendimento,
        horaent as hora_atendimento,
        dtsaida as data_saida,
        horasai as hora_saida,
    from `rj-smas`.`brutos_acolherio_staging`.`gh_atend_familia`
)
select
    *,
    concat(id_atendimento, modulo) as id_atendimento_modulo
from source
)
),

atendimentos_explodidos AS (
    -- Mantém o profissional principal e cada entrada não vazia da lista original.
    SELECT b.* REPLACE (safe_cast(trim(cast(b.id_profissional as string)) as int64) AS id_profissional)
    FROM base_atendimentos AS b

    UNION ALL

    SELECT b.* REPLACE (safe_cast(trim(regexp_replace(prof_id, r'^0+', '')) AS int64) AS id_profissional)
    FROM base_atendimentos AS b
    CROSS JOIN unnest(split(b.id_profissional_compartilhado)) AS prof_id
    WHERE prof_id != ''
),

enriquecidos AS (
    SELECT
        b.modulo,
        e.cas,
        CASE
            WHEN e.nome_unidade LIKE 'ALBERGUE%' THEN 'ALBERGUE'
            WHEN e.nome_unidade LIKE 'CRAF%' THEN 'CENTRAL DE RECEPÇÃO'
            WHEN e.nome_unidade LIKE 'CRAS%' THEN 'CRAS'
            WHEN e.nome_unidade LIKE 'CREAS%' THEN 'CREAS'
            WHEN e.nome_unidade LIKE 'CRI%' THEN 'CENTRAL DE RECEPÇÃO'
            WHEN e.nome_unidade LIKE 'REPÚBLICA%' THEN 'REPÚBLICA'
            WHEN e.nome_unidade LIKE 'URS%' THEN 'URS'
            WHEN e.nome_unidade LIKE 'CENTRO POP%' THEN 'CENTRO POP'
            WHEN e.nome_unidade LIKE 'ESCRITÓRIO%' THEN 'ESCRITÓRIO SOCIAL'
            WHEN e.nome_unidade LIKE 'LARES%' THEN 'LARES CARIOCAS'
            ELSE 'UNIDADE CONVENIADA'
        END AS tipo_unidade,
        e.nome_unidade AS unidade_atendimento,
        e.email_unidade,
        coalesce(
  case
    when lower(e.cas) = '10' then 'cas10@prefeitura.rio'
    when lower(e.cas) = '09' then 'cas9@prefeitura.rio'
    when lower(e.cas) = '08' then 'cas8@prefeitura.rio'
    when lower(e.cas) = '07' then 'cas7@prefeitura.rio'
    when lower(e.cas) = '06' then 'cas6@prefeitura.rio'
    when lower(e.cas) = '05' then 'cas5@prefeitura.rio'
    when lower(e.cas) = '04' then 'cas4@prefeitura.rio'
    when lower(e.cas) = '03' then 'cas3@prefeitura.rio'
    when lower(e.cas) = '02' then 'cas2@prefeitura.rio'
    when lower(e.cas) = '01' then 'cas1@prefeitura.rio'
  end
, 'gdados.smas@prefeitura.rio') AS email_cas,
        b.id_atendimento AS seq_atendimento,
        b.data_atendimento AS data_de_atendimento,
        b.hora_atendimento AS hora_de_atendimento_original,
        format('%02d:%02d', div(b.hora_atendimento, 100), mod(b.hora_atendimento, 100)) AS hora_de_atendimento,
        b.id_paciente AS id_usuario,
        b.id_familia,
        p.nome AS nome_usuario,
        CASE WHEN p.cpf IS null OR p.cpf = '' THEN 'CPF não informado' ELSE 'CPF informado' END AS documentacao,
        CASE
            WHEN p.cpf IS null OR p.cpf = ''
                THEN null
            ELSE
                concat(
                    substring(lpad(p.cpf, 11, '0'), 1, 3), '.',
                    substring(lpad(p.cpf, 11, '0'), 4, 3), '.',
                    substring(lpad(p.cpf, 11, '0'), 7, 3), '-',
                    substring(lpad(p.cpf, 11, '0'), 10, 2)
                )
        END AS numero_documento,
        trim(regexp_replace(p.logradouro, r'[,\s;]+', ' ')) AS endereco,
        trim(regexp_replace(p.numero_endereco, r'[,\s;]+', ' ')) AS endereco_numero,
        trim(regexp_replace(p.complemento_endereco, r'[,\s;]+', ' ')) AS endereco_complemento,
        CASE
            WHEN p.bairro = '' THEN 'NAO INFORMADO'
            ELSE p.bairro
        END AS bairro,
        trim(regexp_replace(p.ponto_referencia, r'[,\s;]+', ' ')) AS referencia_ou_comunidade,
        c.descricao AS nome_atendimento_original,
        p.data_nascimento,
        date_diff(current_date(), p.data_nascimento, YEAR)
        - if(extract(DAYOFYEAR FROM p.data_nascimento) > extract(DAYOFYEAR FROM current_date()), 1, 0) AS idade,
        CASE
            WHEN p.raca_cor = '01' THEN 'Branca'
            WHEN p.raca_cor = '02' THEN 'Preta'
            WHEN p.raca_cor = '03' THEN 'Parda'
            WHEN p.raca_cor = '04' THEN 'Amarela'
            WHEN p.raca_cor = '05' THEN 'Indigena'
            ELSE 'Nao informado'
        END AS raca_cor,
        p.sexo,
        q.id_profissional AS profissional_id,

        CASE
            WHEN trim(upper(q.nome)) IN ('ATENDIMENTO RECEPÇÃO', 'ATENDIMENTO BUSCA ATIVA', 'ATENDIMENTO ENTREVISTADOR SOCIAL')
                THEN trim(upper(s.nome_operador))
            ELSE trim(upper(q.nome))
        END AS profissional,

        cb.descricao AS profissional_cbo_original,
        CASE
            WHEN cb.descricao LIKE 'Articulador Comunitário%' THEN 'Articulador Comunitário'
            WHEN cb.descricao LIKE 'Assistente administrativo%' THEN 'Assistente administrativo'
            WHEN cb.descricao LIKE 'Assistente Social%' THEN 'Assistente social'
            WHEN cb.descricao LIKE 'Assistente social%' THEN 'Assistente social'
            WHEN cb.descricao LIKE 'Educador social%' THEN 'Educador social'
            WHEN cb.descricao LIKE 'Entrevistador Social%' THEN 'Entrevistador social'
            WHEN cb.descricao LIKE 'Pedagogo%' THEN 'Pedagogo'
            WHEN cb.descricao LIKE 'Psicólogo%' THEN 'Psicólogo'
            WHEN cb.descricao LIKE 'Recepcionista%' THEN 'Recepcionista'
            ELSE cb.descricao
        END AS profissional_cbo,
        trim(upper(s.nome_operador)) AS cadastrante,
        b.data_cadastro_atendimento,
        b.id_unidade AS _id_unidade,
        b.id_tipo_atendimento AS _id_tipo_atendimento,
        b.flag_cancelado AS _flag_cancelado

    FROM atendimentos_explodidos AS b
    INNER JOIN (
-- Camada Raw: Dados cadastrais dos pacientes
with source as (
    select
        seqpac as id_paciente,
        sequsref as id_unidade_referencia,
        seqlogin as id_login_cadastro,
        sigufnasc as uf_nascimento,
        muninasc as cidade_nascimento,
        dscnomepac as nome,
        dscnomsoci as nome_social,
        dscnmmae as nome_mae,

  CASE
    WHEN estcivil = '1' THEN 'Solteiro'
    WHEN estcivil = '2' THEN 'Casado'
    WHEN estcivil = '3' THEN 'Viúvo'
    WHEN estcivil = '4' THEN 'Separado Judicialmente'
    WHEN estcivil = '5' THEN 'União consensual'
  END
 as estado_civil,
        datnascim as data_nascimento,
        nacional as nacionalidade,
        condestr as condicao_estrangeira,
        paisorigem as pais_origem,
        dscbairroender as bairro,
        dslogradouro as logradouro,
        numend as numero_endereco,
        complend as complemento_endereco,
        pontorefe as ponto_referencia,
        racacor as raca_cor,
        numcpfpac as cpf,
        indsexo as sexo,
        indgenero as genero,
        nuprontpapel as prontuario_papel,
        datcadast as data_cadastro,
        numrg as numero_rg_cadastro,
        dsccns as nis_cadastro
    from `rj-smas`.`brutos_acolherio_staging`.`gh_cidadao_pac`
)

select * from source
) AS p ON b.id_paciente = p.id_paciente
    LEFT JOIN (
-- Camada Raw: Tipos de atendimento
with source as (
    select
        seqtpatend as id_tipo_atendimento,
        descatend as descricao,
        codabapront as codigo_aba_prontuario,
        descatend as tipo_atendimento_descricao
    from `rj-smas`.`brutos_acolherio_staging`.`gh_tpatendimentos`
)
select * from source
) AS c ON b.id_tipo_atendimento = c.id_tipo_atendimento
    LEFT JOIN (
-- Camada Raw: Limpeza e renomeação inicial da fonte de unidades
-- Sistema original: Prontuário Carioca de Assistência Social (ex-Acolherio)

with source as (
    select
        sequs as id_unidade,
        dscus as nome_unidade,
        apus as cas,
        siguf as uf,
        esfera,
        seqtipous as id_tipo_unidade,
        emailprof as email_unidade,
        (indinativo <> 'S') as flag_unidade_ativa
    from `rj-smas`.`brutos_acolherio_staging`.`gh_us`
)

select * from source
) AS e ON b.id_unidade = e.id_unidade
    LEFT JOIN (
-- Camada Raw: Operadores (contas de login) do sistema
with source as (
    select
        seqlogin as id_login,
        nompess as nome_operador,
        dscemail as email,
        dsclogin as login,
        indnivel as nivel_conta,
        indtypeacess as tipo_acesso_codigo,
        indstatuser as status_conta_codigo,
        datcadastro as data_cadastro,
        datultacess as data_ultimo_acesso
    from `rj-smas`.`brutos_acolherio_staging`.`gh_contas`
)
select * from source
) AS s ON b.id_login_cadastro = s.id_login
    LEFT JOIN (
-- Camada Raw: Profissionais do Prontuário Carioca
with source as (
    select
        seqprof as id_profissional,
        sequs as id_unidade,
        seqlogin as id_login,
        nomgue as nome_guerra,
        crmbloq as flag_bloqueio,
        matrprof as matricula,
        sigufconselho as uf_conselho,
        nomeprof as nome,
        nomsocprof as nome_social,
        indusonomsoc as flag_uso_nome_social,
        codcns as cns,
        cpfprof as cpf,
        indsexo as sexo,
        indgenero as genero,
        indativo as flag_ativo,
        dtcadast as data_cadastro,
        datultmodif as data_ultima_modificacao,
        emailprof as email,
        dsctel as telefone,
    from `rj-smas`.`brutos_acolherio_staging`.`gh_prof`
)
select * from source
) AS q ON b.id_profissional = q.id_profissional
    LEFT JOIN (
-- Camada Raw: Vínculo entre profissionais e CBOs
with source as (
    select
        seqprof as id_profissional,
        codcbo as codigo_cbo
    from `rj-smas`.`brutos_acolherio_staging`.`gh_profocup`
)
select * from source
) AS v ON q.id_profissional = v.id_profissional
    LEFT JOIN (
-- Camada Raw: Cadastro de CBO (Classificação Brasileira de Ocupações)
with source as (
    select
        codcbo as codigo_cbo,
        dsccbo as descricao,
    from `rj-smas`.`brutos_acolherio_staging`.`gh_cbo`
)
select * from source
) AS cb ON v.codigo_cbo = cb.codigo_cbo

    WHERE
        s.nome_operador NOT LIKE '%TESTE%'
        AND p.nome NOT LIKE '%TESTE%'
        AND e.nome_unidade NOT LIKE '%TESTE%'
),

classificados AS (
    SELECT
        a.*,
        CASE
            WHEN a.nome_atendimento_original LIKE '%Recepção%' THEN 'Atendimento Recepção'
            WHEN a.profissional = 'ATENDIMENTO RECEPÇÃO' THEN 'Atendimento Recepção'
            WHEN
                a.profissional_cbo IN ('Administrador', 'Articulador Comunitário', 'Assistente administrativo', 'Educador social', 'Orientador social', 'Recepcionista')
                AND a.nome_atendimento_original LIKE '%CadÚnico%'
                THEN 'Atendimento Recepção'
            WHEN a.profissional_cbo IN ('Advogado', 'Assistente social', 'Pedagogo', 'Psicólogo') THEN 'Atendimento Técnico'
            ELSE 'Outros Atendimentos'
        END AS tipo_atendimento,
        CASE
            WHEN
                a.profissional_cbo IN ('Administrador', 'Articulador Comunitário', 'Assistente administrativo', 'Educador social', 'Orientador social', 'Recepcionista')
                AND a.tipo_unidade = 'CRAS'
                AND a.nome_atendimento_original LIKE '%CadÚnico%'
                THEN 'CRAS - Recepção - Ação CadÚnico'
            WHEN
                a.profissional_cbo IN ('Administrador', 'Articulador Comunitário', 'Assistente administrativo', 'Educador social', 'Orientador social', 'Recepcionista')
                AND a.tipo_unidade = 'CREAS'
                AND a.nome_atendimento_original LIKE '%CadÚnico%'
                THEN 'CREAS - Recepção - Ação CadÚnico'
            ELSE a.nome_atendimento_original
        END AS nome_atendimento,
        CASE
            WHEN a.idade < 18 THEN 'Até 17 anos'
            WHEN a.idade >= 18 AND a.idade < 30 THEN 'De 18 a 29 anos'
            WHEN a.idade >= 30 AND a.idade < 45 THEN 'De 30 a 44 anos'
            WHEN a.idade >= 45 AND a.idade < 60 THEN 'De 45 a 59 anos'
            WHEN a.idade >= 60 AND a.idade < 75 THEN 'De 60 a 74 anos'
            WHEN a.idade >= 75 THEN 'Mais de 75 anos'
            ELSE 'Não Informado'
        END AS idade_faixa,

        concat(a.seq_atendimento, '-', a.profissional_id) AS id_atendimento,
        concat(a.email_cas, ',', a.email_unidade, ',', z.email) AS email
    FROM enriquecidos AS a
    LEFT JOIN (
-- Camada Raw: Filtro de e-mails por unidade (planilha de apoio do dashboard)
with source as (
    select
        UNIDADE_ATENDIMENTO as unidade_atendimento,
        EMAIL as email
    from `rj-smas-dev`.`dashboard_acolherio`.`filtro_email_dev`
)
select * from source
) AS z ON a.unidade_atendimento = z.unidade_atendimento
),

-- Seleção de projetos ativos no cadastro familiar, inclusive para atendimentos antigos.
projetos_ativos AS (
    SELECT
        id_familia,
        coalesce(

-- Referência: catálogo auxiliar de 09/10/2026; sem dependência de CI em execução.
case safe_cast(id_projeto_social as int64)
    when 1 then "Territórios Sociais"
    when 2 then "Pequenos Cariocas"
    when 3 then "MCMV - Minha Casa Minha Vida"
    when 4 then "Alimenta Rio"
    when 5 then "Banco de Alimentos/Cozinha Comunitária"
    when 6 then "Banco Carioca de Bolsa de Estudos"
    when 7 then "Projetos de Empreendedorismo"
    when 8 then "PRONASCI Juventude"
    when 9 then "Agente Experiente"
    when 10 then "Amparando Filhos"
    when 11 then "Bora pra Escola"
    when 12 then "DAM+"
    when 13 then "De Mãos Dadas"
    when 14 then "De Volta a Terra Natal"
    when 15 then "Escritório Social"
    when 16 then "Garupa"
    when 17 then "Guarda Subsidiada"
    when 18 then "Jovem Aprendiz"
    when 19 then "Lares Cariocas"
    when 20 then "Moradia com Apoio"
    when 21 then "Novos Rumos"
    when 22 then "Passo a Passo"
    when 23 then "Penas e Medidas Alternativas"
    when 24 then "PETI - Errad. Trab. Infantil"
    when 25 then "Projetos de Qualificação Profissional"
    when 26 then "Reinserção familiar ou comunitária"
    when 27 then "SUAS Acolhendo Talentos"
    when 28 then "Vem com a gente"
    when 29 then "Rio Dignidade"
    when 30 then "Idoso em Família"
    when 31 then "Projovem Urbano"
    when 32 then "Tô de Boa"
end
,
            format('Projeto não mapeado (ID %d)', id_projeto_social)
        ) AS nome_projeto
    FROM (
-- Camada Raw: Projetos sociais das famílias
with source as (
    select
        seqfamil as id_familia,
        seqprojsoc as id_projeto_social,
        sequs as id_unidade,
        seqlogincad as id_login_cadastro,
        datcadastr as data_cadastro,
        datcancel as data_cancelamento,
        indativo as indicador_ativo
    from `rj-smas`.`brutos_acolherio_staging`.`gh_famil_projsociais`
)
select * from source
)
    WHERE indicador_ativo = 'S' AND data_cancelamento IS null
),

projetos_por_familia AS (
    SELECT
        id_familia,
        string_agg(DISTINCT nome_projeto, ', ' ORDER BY nome_projeto) AS projetos_sociais
    FROM projetos_ativos
    GROUP BY id_familia
),

classificacao AS (









    select
        a.*,
        -- Cópias idênticas podem liderar o primeiro ranking. O segundo mantém só uma.
        rank() over (
            partition by id_atendimento
            order by
                a.data_cadastro_atendimento asc nulls first,
                a.seq_atendimento asc,
                a.modulo asc,
                to_json_string(struct(a.modulo, a.cas, a.tipo_unidade, a.unidade_atendimento, a.email_unidade, a.email_cas, a.seq_atendimento, a.data_de_atendimento, a.hora_de_atendimento_original, a.hora_de_atendimento, a.id_usuario, a.id_familia, a.nome_usuario, a.documentacao, a.numero_documento, a.endereco, a.endereco_numero, a.endereco_complemento, a.bairro, a.referencia_ou_comunidade, a.nome_atendimento_original, a.data_nascimento, a.idade, a.raca_cor, a.sexo, a.profissional_id, a.profissional, a.profissional_cbo_original, a.profissional_cbo, a.cadastrante, a.data_cadastro_atendimento, a.tipo_atendimento, a.nome_atendimento, a.idade_faixa, a.id_atendimento, a.email)) asc
        ) as cbo_unico_rank,
        row_number() over (
            partition by
                profissional_id, hora_de_atendimento, data_de_atendimento,
                nome_atendimento_original, id_usuario, unidade_atendimento
            order by
                a.data_cadastro_atendimento asc nulls first,
                a.seq_atendimento asc,
                a.modulo asc,
                to_json_string(struct(a.modulo, a.cas, a.tipo_unidade, a.unidade_atendimento, a.email_unidade, a.email_cas, a.seq_atendimento, a.data_de_atendimento, a.hora_de_atendimento_original, a.hora_de_atendimento, a.id_usuario, a.id_familia, a.nome_usuario, a.documentacao, a.numero_documento, a.endereco, a.endereco_numero, a.endereco_complemento, a.bairro, a.referencia_ou_comunidade, a.nome_atendimento_original, a.data_nascimento, a.idade, a.raca_cor, a.sexo, a.profissional_id, a.profissional, a.profissional_cbo_original, a.profissional_cbo, a.cadastrante, a.data_cadastro_atendimento, a.tipo_atendimento, a.nome_atendimento, a.idade_faixa, a.id_atendimento, a.email)) asc,
                to_json_string(struct(a._id_unidade, a._id_tipo_atendimento, a._flag_cancelado)) asc
        ) as atendimento_unico_rank
    from classificados as a
    qualify cbo_unico_rank = 1 and atendimento_unico_rank = 1

)

SELECT
    a.*,
    p.projetos_sociais
FROM classificacao AS a
LEFT JOIN projetos_por_familia AS p ON a.id_familia = p.id_familia
) as a;
